rows.vgi.example_queries:
[
  {"description": "Defang a live URL so it is safe to paste into a report (returns 'hxxp[://]evil[.]com/x').", "sql": "SELECT ioc.main.defang('http://evil.com/x');"},
  {"description": "Turn a live incident note into a safe-to-share watchlist: extract every indicator with extract_iocs, then defang each value so none of them is clickable.", "sql": "SELECT i.type, ioc.main.defang(i.value) AS shareable FROM ioc.main.extract_iocs('beacon to http://evil.com/gate.php from 10.0.0.5, contact bad@evil.com') AS i ORDER BY i.type, shareable"}
]

[
  {"description": "Pull a CVE identifier out of a report (returns 'CVE-2024-1234').", "sql": "SELECT UNNEST(ioc.main.extract_cves('exploiting CVE-2024-1234 in the wild'));"}
]

[
  {"description": "Pull a bare defanged domain out of a report (returns 'evil.example.com').", "sql": "SELECT UNNEST(ioc.main.extract_domains('callback to evil[.]example[.]com'));"}
]

[
  {"description": "Pull a defanged e-mail address out of a report (returns 'bad@evil.com').", "sql": "SELECT UNNEST(ioc.main.extract_emails('phish from bad[at]evil[.]com'));"}
]

[
  {"description": "Pull a file hash out of a report (returns 'd41d8cd98f00b204e9800998ecf8427e').", "sql": "SELECT UNNEST(ioc.main.extract_hashes('sample md5 d41d8cd98f00b204e9800998ecf8427e'));"},
  {"description": "For each alert in a table, list the file hashes it mentions with their algorithm: unnest extract_hashes over the alert text and label each hash with hash_type (alerts without hashes produce no rows).", "sql": "WITH alerts(id, body) AS (VALUES (1, 'dropped d41d8cd98f00b204e9800998ecf8427e and da39a3ee5e6b4b0d3255bfef95601890afd80709'), (2, 'user reset password'), (3, 'payload e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855')) SELECT a.id, h.hash, ioc.main.hash_type(h.hash) AS algorithm FROM alerts AS a, UNNEST(ioc.main.extract_hashes(a.body)) AS h(hash) ORDER BY a.id, algorithm"}
]

rows.vgi.result_columns_schema:
[
  {"name": "type", "type": "VARCHAR", "description": "Indicator type: one of ipv4, ipv6, url, email, domain, md5, sha1, sha256, sha512, cve."},
  {"name": "value", "type": "VARCHAR", "description": "The refanged (live-form) indicator value."}
]

