[
  {"description": "Pull the defanged IPv4 address out of a report (returns '10.0.0.5').", "sql": "SELECT UNNEST(ioc.main.extract_ipv4('beacon from 10[.]0[.]0[.]5'));"}
]

[
  {"description": "Pull an IPv6 address out of free text (returns '2001:db8::1').", "sql": "SELECT UNNEST(ioc.main.extract_ipv6('C2 at 2001:db8::1 observed'));"}
]

[
  {"description": "Pull a defanged URL out of a report (returns 'http://evil.com/x').", "sql": "SELECT UNNEST(ioc.main.extract_urls('payload from hxxp://evil[.]com/x'));"}
]

[
  {"description": "Classify a 32-character hex string as an MD5 hash (returns 'md5').", "sql": "SELECT ioc.main.hash_type('d41d8cd98f00b204e9800998ecf8427e');"},
  {"description": "For each alert in a table, list the file hashes it mentions with their algorithm: unnest extract_hashes over the alert text and label each hash with hash_type (alerts without hashes produce no rows).", "sql": "WITH alerts(id, body) AS (VALUES (1, 'dropped d41d8cd98f00b204e9800998ecf8427e and da39a3ee5e6b4b0d3255bfef95601890afd80709'), (2, 'user reset password'), (3, 'payload e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855')) SELECT a.id, h.hash, ioc.main.hash_type(h.hash) AS algorithm FROM alerts AS a, UNNEST(ioc.main.extract_hashes(a.body)) AS h(hash) ORDER BY a.id, algorithm"}
]

[
  {"description": "Test whether free text contains any indicator of compromise (returns true).", "sql": "SELECT ioc.main.is_ioc('beacon to 10[.]0[.]0[.]5');"},
  {"description": "Triage a ticket queue: keep only tickets whose text contains any indicator (is_ioc), then count the IPv4 addresses, URLs and CVEs each one mentions.", "sql": "WITH tickets(id, body) AS (VALUES (1, 'beacon to hxxp://evil[.]com/x from 10[.]0[.]0[.]5'), (2, 'password reset for jsmith'), (3, 'exploiting CVE-2024-1234 via 10[.]0[.]0[.]5 and 10[.]0[.]0[.]9'), (4, 'printer offline on floor 3')) SELECT id, len(ioc.main.extract_ipv4(body)) AS n_ips, len(ioc.main.extract_urls(body)) AS n_urls, len(ioc.main.extract_cves(body)) AS n_cves FROM tickets WHERE ioc.main.is_ioc(body) ORDER BY id"}
]

[
  {"description": "Refang a defanged URL back to live form (returns 'http://evil.com').", "sql": "SELECT ioc.main.refang('hxxp://evil[.]com');"}
